import type { TheoryBankQuestion } from "../../scripts/import-theory";

type Code = "sv" | "en" | "ti" | "ar" | "so";
type Row = [string, string, string, string, string];

function pack(row: Row) {
  return {
    question: row[0],
    options: [row[1], row[2], row[3]] as [string, string, string],
    explanation: row[4],
  };
}

function item(
  id: string,
  parm: number,
  correct: number,
  difficulty: 1 | 2 | 3,
  text: Record<Code, Row>,
): TheoryBankQuestion {
  const sv = pack(text.sv);
  return {
    id,
    parm,
    question_sv: sv.question,
    options_sv: [...sv.options],
    explanation_sv: sv.explanation,
    correct_index: correct,
    difficulty,
    needs_image: false,
    status: "ok",
    translations: {
      en: pack(text.en),
      ti: pack(text.ti),
      ar: pack(text.ar),
      so: pack(text.so),
    },
  };
}

